weak_encryption_patterns := {"DES", "3DES", "RC4", "AES[-_]?128", "AES[-_]?ECB", "AES[-_]?GCM[-_]?128", "md5_crypt"}
outdated_protocol_patterns := {"SSLv2", "SSLv3", "TLSv1\\.0", "TLSv1\\.1", "SSHv1"}
insecure_hash_patterns := {"MD5", "SHA[-_]?1", "RSA_WITH_MD5", "ECDSA_WITH_SHA1", "sha1"}
weak_key_derivation_patterns := {"PBKDF1", "unsalted"}
implementation_flaw_patterns := {"ECB", "true", "false"}
hardcoded_key_patterns := {"true", "NONE", "CUSTOM"}

get_string_value(value) = str {
    value.ir_type == "String"
    str := lower(value.value)
} else {
    value.ir_type == "FunctionCall"
    count(value.args) > 0
    arg := value.args[_]
    arg.ir_type == "String"
    str := lower(arg.value)
} else {
    value.ir_type == "Access"
    value.right.ir_type == "String"
    str := lower(value.right.value)
} else {
    str := ""
}

contains_pattern(str, patterns) = result {
    pattern := patterns[_]
    regex.match(sprintf("(?i).*%s.*", [pattern]), str)
    result := true
}

check_attribute(node, name_patterns, value_patterns, description) = result {
    node.ir_type == "Attribute"
    name_lower := lower(node.name)
    contains_pattern(name_lower, name_patterns)
    string_value := get_string_value(node.value)
    string_value != ""
    contains_pattern(string_value, value_patterns)
    result := {
        "type": "sec_weak_crypt",
